from pathlib import Path
import json,hashlib,re
O=Path(__file__).resolve().parents[1];B=O.parent
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
r=json.loads((O/'recomputation.json').read_text());before=json.loads((O/'inputs-before.json').read_text());extra=json.loads((O/'inputs-supplemental-before.json').read_text())
after={p:sha(B/p) for p in before};ea={p:sha(B/p) for p in extra};assert before==after and extra==ea
(O/'inputs-after.json').write_text(json.dumps(after,indent=2)+'\n');(O/'inputs-supplemental-after.json').write_text(json.dumps(ea,indent=2)+'\n')
for a in json.loads((O/'receipts/source-copies.json').read_text()):assert sha(O/a['copy'])==a['sha256']==sha(B/a['original'])
assert sha(O/'lean-source.zip')==sha(B/'delta-formal-r3/source.zip')=='c0dba5dc4f6738531b09750bd5e6f46ba565ba952f50fbe927e4f9cfe4a0e08c'
info=(O/'receipts/pdfinfo.txt').read_text();pages=int(re.search(r'Pages:\s+(\d+)',info)[1]);assert pages==7
j=(O/'sources/expanded-corpus-r153/sources/delta-journal.txt').read_text();assert all(s in j for s in ['11 (2024), 641–682','10.4171/AIHPD/172','Conjecture 5.1.','Definition 2.1.'])
raw=O/'sources/352253.raw.jsonl';assert len(raw.read_bytes().splitlines())==1 and json.loads(raw.read_text())['mathdb_id']==352253
qa={'status':'PASS','pdf_sha256':sha(O/'paper.pdf'),'pages':pages,'method':'pdftoppm at 100 dpi; every final page viewed individually with view_image','observations':'All final pages legible; no clipping, overlaps, missing glyphs, or overflow. Long pure-index line wrapped after first inspection; final seven pages re-inspected. Page 6 body clears footer.','images':{p.name:sha(p) for p in sorted((O/'qa').glob('page-*.png'))}}
assert len(qa['images'])==pages;(O/'receipts/visual-QA.json').write_text(json.dumps(qa,indent=2)+'\n')
ledger={'fresh_computation':{k:r[k] for k in ['states','legal_move_arcs','states_by_order','minimum_order','labelled_minima','chain_free_minima','end_bases','pure_centres','pure_orders','witness_operations','witness_orders','packet_modules','closure_chunks','safe_members']},'matrix_and_labels':'Every edge, matrix entry, centre, triangle, order, and displayed gadget mapping regenerated in recomputation.json. Positive alias control passes. Chunk size recomputed: 2328/582 = 4.','bibliographic_numbers':'Journal volume/year/pages/DOI verified in cached source header; conjecture, figure, definition and module numbers are identifiers, not estimated counts. Bibliographic arXiv IDs verified against copied source/review provenance.','inherited_replay':'No new numerical performance claim is printed; PASS and axiom claims attributed to hash-bound root receipts. Earlier Closure276 failure retained as historical identifier.','raw_line_sha256':sha(raw)}
assert r['states']//r['closure_chunks']==4 and r['states']%r['closure_chunks']==0
(O/'receipts/number-provenance.json').write_text(json.dumps(ledger,indent=2)+'\n')
status={'mathdb_id':352253,'status':'DRAFT_DOSSIER_COMPLETE_NOT_ACCEPTANCE','accepted':False,'credit':0,'root_alone_accepts':True,'ai_assisted':True,'pdf_pages':pages,'fresh_numerical_check':'PASS','offline_reproduction':'PASS','input_integrity':'PASS','initial_bound_files':len(before),'supplemental_bound_files':len(extra),'safe_extraction':'PASS; no packet execution','lean_executed_by_this_task':False,'lean_packet_sha256':sha(O/'lean-source.zip'),'endpoint':'Round2.literal_negation : ¬ Literal.Conjecture51','inherited_root_replay':'PASS (delta-parent-final-r2/replay-result.json)','chain_qualification':'Illustrated edge-distinct capacity reading; apex and attachment coincidences permitted','significance':'qualified, modest; no priority claim','figure14_timing_correction':'(c) after one expansion in seven-move trace; (c) and (g) after two expansions in original nine-move trace, not both after the shorter first expansion','visual_QA':'PASS; every final page inspected','running_jobs_at_handback':False,'deliverables':['paper.pdf','paper.md','paper.ps','PROOF.md','REPRODUCE.md','lean-source.zip','dossier.zip','MANIFEST.sha256','archive-receipt.json'],'remaining':'Root manuscript read, acceptance decision; no self-acceptance.'}
(O/'results.json').write_text(json.dumps(status,indent=2)+'\n')
(O/'SUMMARY.md').write_text('''# MathDB 352253 — draft dossier complete, zero accepted credit

Seven-page AI-assisted draft: paper.pdf; editable sources: paper.md, paper.template.md and paper.ps. Full dossier: dossier.zip. Byte-identical formal packet: lean-source.zip. Root alone accepts.

Fresh independent source-definition recomputation confirms 2,328 labelled pure states, 9,846 legal-centre arcs, minimum order 11, and 25 chain-free labelled minima. The seven-move witness reaches order 10. All numerical statements and matrices are regenerated; the exact raw MathDB JSONL line and its hash are preserved. Standalone offline recomputation passes using copied inputs, without any Lean invocation. All seven final PDF pages were rendered and visually inspected.

The chain claim uses the illustrated edge-distinct capacity reading, allowing apex/attachment coincidences; it does not reuse the earlier restricted incidence test. Significance is qualified and modest, with no priority claim. The manuscript preserves the source-known Figure 14 relationship and sharpens the brief's timing: (c) appears after one expansion in the shorter trace; both (c) and (g) appear after two expansions in the original detoured trace. No printed gadget occurs in the initial H.

Round-two independent fidelity review held replay at Closure276. Its qualified definitions/bridge verdict is preserved. Round-three smaller census checks and narrower imports retained the data/statements, and the root's subsequent receipt reports a full strict replay PASS for the hash-bound packet. This worker reused those receipts and ran no Lean, lake or leanchecker. Packet SHA-256: c0dba5dc4f6738531b09750bd5e6f46ba565ba952f50fbe927e4f9cfe4a0e08c.

Initial and supplemental frozen-input before/after hashes match; source-copy hashes match originals. Scripts are isolated Python, capped, serialized, and local. No network, git, children, publication, accounts, external messages, browser tabs, other-lane writes, or shared-ledger edits. No running jobs at handback. Earlier checker development failures (child-pair format and an overstrong Figure 14 timing assertion) were corrected and the final checker rerun successfully; resource logs preserve their nonzero exits.

PROOF.md, REPRODUCE.md, results.json, receipts/, QA PNGs, source copies, input manifests and the deliverable manifest are included. The archive receipt is external to avoid circular hashes. Scratch extraction directories are excluded from the ZIP; the original packet and complete extraction hashes are included. The live resources.jsonl is excluded from deliverable hashing; its stable prepackaging snapshot is separately included. Acceptance and any broader prior-art or priority assessment remain root responsibilities.
''')
